package com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.sharedKernel.businesslogic.models.DateTimeProvider;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.gateways.AvatarMediaRepository;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.models.AvatarMediaStatus;import jakarta.transaction.Transactional;import java.util.UUID;
public class CompleteAvatarMediaDeletion{private final AvatarMediaRepository media;private final DateTimeProvider clock;public CompleteAvatarMediaDeletion(AvatarMediaRepository media,DateTimeProvider clock){this.media=media;this.clock=clock;}@Transactional public void complete(UUID id){var item=media.byId(id).orElse(null);if(item==null)return;var now=clock.now();if(item.snapshot().status()==AvatarMediaStatus.PENDING)item.requestDeletion(now);if(item.markDeleted(now))media.save(item);}}
